166	    Future<List<BidderPrivacyResult>> mask(AuctionContext auctionContext,
167	                                           Map<String, User> bidderToUser,
168	                                           List<String> bidders,
169	                                           BidderAliases aliases) {
170	
171	        final BidRequest bidRequest = auctionContext.getBidRequest();
172	        final Account account = auctionContext.getAccount();
173	        final MetricName requestType = auctionContext.getRequestTypeMetric();
174	        final Device device = bidRequest.getDevice();
175	        final PrivacyContext privacyContext = auctionContext.getPrivacyContext();
176	
177	        final Privacy privacy = privacyContext.getPrivacy();
178	
179	        // For now, COPPA masking all values, so we can omit GDPR masking.
180	        if (isCoppaMaskingRequired(privacy)) {
181	            return Future.succeededFuture(maskCoppa(bidderToUser, device));
182	        }
183	
184	        updateCcpaMetrics(privacy.getCcpa());
185	        final Map<String, BidderPrivacyResult> ccpaResult =
186	                ccpaResult(bidRequest, account, bidders, aliases, device, bidderToUser, privacy);
187	
188	        final Set<String> biddersToApplyTcf = new HashSet<>(bidders);
189	        biddersToApplyTcf.removeAll(ccpaResult.keySet());
190	
191	        return getBidderToEnforcementAction(privacyContext.getTcfContext(), biddersToApplyTcf, aliases, account)
192	                .map(bidderToEnforcement -> updatePrivacyMetrics(
193	                        bidderToEnforcement, aliases, requestType, device))
194	                .map(bidderToEnforcement -> getBidderToPrivacyResult(
195	                        biddersToApplyTcf, bidderToUser, device, bidderToEnforcement))
196	                .map(gdprResult -> merge(ccpaResult, gdprResult));
197	    }
