199	    private Map<String, BidderPrivacyResult> ccpaResult(BidRequest bidRequest,
200	                                                        Account account,
201	                                                        List<String> bidders,
202	                                                        BidderAliases aliases,
203	                                                        Device device,
204	                                                        Map<String, User> bidderToUser,
205	                                                        Privacy privacy) {
