207	        if (isCcpaEnforced(privacy.getCcpa(), account)) {
208	            return maskCcpa(extractCcpaEnforcedBidders(bidders, bidRequest, aliases), device, bidderToUser);
209	        }
210	
211	        return Collections.emptyMap();
212	    }
